Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Executive cybersecurity triage concentration matrix",
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "background": "transparent",
  "transform": [
    {
      "filter": "datum[''Technology Rank''] <= 5"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "Triage Segment KEVs",
          "as": "Segment Maximum"
        }
      ],
      "groupby": [
        "Triage Segment"
      ]
    },
    {
      "calculate": "datum[''Segment Maximum''] > 0 ? 0.28 + (0.72 * datum[''Triage Segment KEVs''] / datum[''Segment Maximum'']) : 0.28",
      "as": "Cell Opacity"
    }
  ],
  "encoding": {
    "x": {
      "field": "Triage Segment",
      "type": "ordinal",
      "sort": [
        "CRITICAL + LIKELY",
        "REMOTE ZERO-CLICK",
        "PRIV-FREE REMOTE",
        "CRITICAL RANSOMWARE"
      ],
      "scale": {
        "paddingInner": 0.12,
        "paddingOuter": 0.04
      },
      "axis": {
        "title": null,
        "orient": "top",
        "domain": false,
        "ticks": false,
        "labelAngle": 0,
        "labelColor": "#A7B8CE",
        "labelFont": "Segoe UI",
        "labelFontSize": 10,
        "labelFontWeight": "bold",
        "labelPadding": 12,
        "labelLimit": 180
      }
    },
    "y": {
      "field": "Tech Stack Filter",
      "type": "nominal",
      "sort": {
        "field": "Technology KEVs",
        "op": "max",
        "order": "descending"
      },
      "scale": {
        "paddingInner": 0.15,
        "paddingOuter": 0.06
      },
      "axis": {
        "title": null,
        "domain": false,
        "ticks": false,
        "labelColor": "#F3F7FF",
        "labelFont": "Segoe UI",
        "labelFontSize": 11,
        "labelFontWeight": "bold",
        "labelPadding": 14,
        "labelLimit": 220
      }
    },
    "tooltip": [
      {
        "field": "Tech Stack Filter",
        "type": "nominal",
        "title": "Technology"
      },
      {
        "field": "Triage Segment",
        "type": "nominal",
        "title": "Priority Signal"
      },
      {
        "field": "Definition",
        "type": "nominal",
        "title": "Definition"
      },
      {
        "field": "Triage Segment KEVs",
        "type": "quantitative",
        "title": "KEVs",
        "format": ",.0f"
      },
      {
        "field": "Technology KEVs",
        "type": "quantitative",
        "title": "Total Technology KEVs",
        "format": ",.0f"
      }
    ]
  },
  "layer": [
    {
      "mark": {
        "type": "rect",
        "cornerRadius": 8,
        "strokeWidth": 1.5
      },
      "encoding": {
        "color": {
          "field": "Color",
          "type": "nominal",
          "scale": null,
          "legend": null
        },
        "stroke": {
          "field": "Color",
          "type": "nominal",
          "scale": null,
          "legend": null
        },
        "opacity": {
          "field": "Cell Opacity",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "range": [
              0,
              1
            ]
          },
          "legend": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "font": "Segoe UI",
        "fontSize": 15,
        "fontWeight": "bold",
        "color": "#F8FAFC",
        "baseline": "middle",
        "align": "center"
      },
      "encoding": {
        "text": {
          "field": "Triage Segment KEVs",
          "type": "quantitative",
          "format": ",.0f"
        }
      }
    }
  ],
  "config": {
    "view": {
      "stroke": null
    },
    "axis": {
      "grid": false
    }
  }
}'
